from itertools import product
from windows import normalize

def oracle(items):
    if any(a > b for a, b in items):
        raise ValueError
    groups = [{(a, b)} for a, b in items if a < b]
    while True:
        for i in range(len(groups)):
            for j in range(i):
                if any(max(a, c) < min(b, d) for a, b in groups[i] for c, d in groups[j]):
                    groups[j] |= groups.pop(i)
                    break
            else:
                continue
            break
        else:
            return sorted((min(a for a, b in g), max(b for a, b in g)) for g in groups)

intervals = list(product(range(-1, 3), repeat=2))
count = 0
